INSERT INTO wiki_category (id, parent_id, sort, label, label_ko, summary, summary_ko) VALUES ('overview', NULL, 0, 'Overview', '개요', 'The Great Blackout, the eternal winter, and Seoul in the winter of 2126.', '대정전과 영원한 겨울, 그리고 2126년 겨울의 서울.');
